import type { BrightStarRow, ChartConstellation, ChartStar, SkyCatalog } from "@/lib/types";
import raw from "./sky-catalog.json";

/**
 * Static star data bundled with the site (generated by
 * scripts/build_sky_data.py from the repository's data/ folder and HYG v4.1).
 * Used for decorative and demo sky rendering; live data comes from the API.
 *
 * The JSON is validated once at load so the rest of the app gets real types
 * without unchecked casts.
 */

const isNum = (v: unknown): v is number => typeof v === "number" && Number.isFinite(v);
const isStr = (v: unknown): v is string => typeof v === "string";
const isObj = (v: unknown): v is Record<string, unknown> => typeof v === "object" && v !== null;

function parseStarRow(v: unknown): BrightStarRow {
  if (!Array.isArray(v) || v.length !== 5) throw new Error("Bad star row");
  const [name, ra, dec, mag, ci] = v as unknown[];
  if (!isStr(name) || !isNum(ra) || !isNum(dec) || !isNum(mag) || !isNum(ci)) {
    throw new Error(`Bad star row: ${JSON.stringify(v)}`);
  }
  return [name, ra, dec, mag, ci];
}

function parseChartStar(v: unknown): ChartStar {
  if (!isObj(v) || !isStr(v.name) || !isNum(v.ra) || !isNum(v.dec) || !isNum(v.magnitude) || !isNum(v.ci)) {
    throw new Error(`Bad constellation star: ${JSON.stringify(v)}`);
  }
  return {
    name: v.name,
    designation: isStr(v.designation) ? v.designation : undefined,
    ra: v.ra,
    dec: v.dec,
    magnitude: v.magnitude,
    ci: v.ci,
  };
}

function parseConstellation(name: string, v: unknown): ChartConstellation {
  if (!isObj(v) || !isStr(v.abbreviation) || !Array.isArray(v.stars) || !Array.isArray(v.lines)) {
    throw new Error(`Bad constellation: ${name}`);
  }
  const stars = v.stars.map(parseChartStar);
  const names = new Set(stars.map((s) => s.name));
  const lines = v.lines.map((line): [string, string] => {
    if (!Array.isArray(line) || line.length !== 2 || !isStr(line[0]) || !isStr(line[1])
        || !names.has(line[0]) || !names.has(line[1])) {
      throw new Error(`Bad line in ${name}: ${JSON.stringify(line)}`);
    }
    return [line[0], line[1]];
  });
  return {
    abbreviation: v.abbreviation,
    stars,
    lines,
    mythology: isStr(v.mythology) ? v.mythology : "",
  };
}

export function parseCatalog(v: unknown): SkyCatalog {
  if (!isObj(v) || !Array.isArray(v.stars) || !isObj(v.constellations)) {
    throw new Error("Bad sky catalogue");
  }
  const constellations: Record<string, ChartConstellation> = {};
  for (const [name, record] of Object.entries(v.constellations)) {
    constellations[name] = parseConstellation(name, record);
  }
  return {
    source: isStr(v.source) ? v.source : "",
    stars: v.stars.map(parseStarRow),
    constellations,
  };
}

export const catalog: SkyCatalog = parseCatalog(raw as unknown);

export const CONSTELLATION_NAMES: string[] = Object.keys(catalog.constellations).sort();

export function getConstellation(name: string): ChartConstellation | undefined {
  return catalog.constellations[name];
}
